<?php

declare(strict_types=1);namespace ProjectPress\Tests\Unit;use PHPUnit\Framework\TestCase;use ProjectPress\API\CompositionRoutes;use ProjectPress\Includes\Core\Schema;use ProjectPress\Includes\Core\WP\Database;use ProjectPress\Includes\Project\Composition\Component;use ProjectPress\Includes\Project\Composition\SBOM;final class PhaseNineCompositionTest extends TestCase{public function testCompositionTablesAreRegistered():void{Schema::register_tables();$tables=Database::get_core_tables();foreach(array('components','packages','composition_assets','composition_licences','attributions','provenance','composition_relationships','sboms')as$table)$this->assertArrayHasKey($table,$tables);}public function testCompositionModelsRemainProjectScoped():void{$this->assertSame(31,(new Component(array('project_id'=>31,'name'=>'Library')))->get_project_id());$this->assertSame(31,(new SBOM(array('project_id'=>31,'format'=>'generic')))->get_project_id());}public function testCoreSbomModelIsFormatAgnostic():void{$sbom=new SBOM(array('project_id'=>31,'format'=>'generic'));$this->assertSame('generic',$sbom->get_format());}public function testCompositionRestHandlersExist():void{foreach(array('snapshot','index','create','update','delete','can_read','can_edit')as$method)$this->assertTrue(method_exists(CompositionRoutes::class,$method));}public function testDeletionOwnsCompositionTables():void{$source=file_get_contents(dirname(__DIR__,2).'/src/Includes/Project/Core/ProjectRepository.php');foreach(array("'components'","'packages'","'composition_assets'","'composition_licences'","'attributions'","'provenance'","'composition_relationships'","'sboms'")as$table)$this->assertStringContainsString($table,$source);}}
